        "يمكن إعادة القياس كل فترة قصيرة أثناء الـ<bdi>treatment</bdi> بدون تأخير أو حاجة لمعدات معقدة، وهذا عملي جدًا ب<bdi>case</bdi> النوبة الـ<bdi>acute</bdi>.",
        "الأشعة الصدرية وغازات الدم فحوصات مفيدة بس أبطأ وأقل عملية لل<bdi>follow-up</bdi> المتكررة السريعة، ونبض متناقض (pulsus paradoxus) <bdi>sign</bdi> فحص سريري مساعدة بس أقل دقة وموضوعية من الرقم المباشر لمقياس ذروة الجريان.",
