        "زرع السائل لل<bdi>tuberculosis</bdi> حساسيته <bdi>low</bdi> جدًا (يحتاج وقت طويل وغالبًا يطلع سلبي رغم وجود الـ<bdi>disease</bdi>)، والغلوكوز الـ<bdi>low</bdi> والنمط اللمفاوي الـ<bdi>exudative</bdi> يدعمان الـ<bdi>diagnosis</bdi> بس أقل حساسية ونوعية من ADA كفحص مفرد.",
