        "<bdi>renal failure</bdi> يرفع الفوسفات ويغير قيم ثانية، وما يعطي هالصورة المحددة من كالسيوم <bdi>elevated</bdi> مع PTH <bdi>low</bdi> بهالسياق الورمي.",
