        "لو الشخص تعرض ل<bdi>patient</bdi> <bdi>tuberculosis</bdi> نشط وفحصه إيجابي كامن، يصير الـ<bdi>treatment</bdi> الوقائي (<bdi>chemoprophylaxis</bdi>) هو المطلوب له تحديدًا.",
