WHY_WRONG.update({
201: {"A": "الأكسجين المنزلي وحده لا يعالج الانسداد الميكانيكي بمجرى الهواء العلوي.", "B": "التيوتروبيوم دواء COPD غير مرتبط ب<bdi>treatment</bdi> انقطاع النفس النومي.", "D": "البريدنيزون الفموي ليس له دور علاجي مثبت بانقطاع النفس النومي."},
202: {"A": "البريدنيزون ليس <bdi>treatment</bdi> موصى به روتينيًا بتوسع القصبات.", "B": "الأسيتيل سيستئين ليس <bdi>treatment</bdi> أساسيًا معتمدًا روتينيًا بتوسع القصبات.", "C": "المحلول الملحي الاستنشاقي مفيد أحيانًا لكن أقل فعالية من التصريف الوضعي المباشر."},
203: {"A": "التهديد بالموت أسلوب ضغط غير أخلاقي وغير فعال لتغيير السلوك.", "C": "تهديده بإشراك الأسرة تجاوز لاستقلاليته وقد يضر بالثقة العلاجية.", "D": "تهديده بإيقاف الرعاية غير أخلاقي ومخالف لواجب استمرار الـ<bdi>treatment</bdi>."},
204: {"A": "قراءة التقرير حرفيًا تستخدم مصطلحات طبية معقدة لا يفهمها الـ<bdi>patient</bdi> العادي.", "B": "<bdi>symptom</bdi> فيلم الأشعة وحده بدون شرح لا يوصل معنى الـ<bdi>diagnosis</bdi> لل<bdi>patient</bdi>.", "C": "ذكر الاسم الطبي فقط (bronchiectasis) بدون شرح مبسط لا يحقق الفهم الفعلي."},
205: {"A": "الظروف المعيشية قد تكون مهمة أحيانًا لكن ليست الأولوية الأولى هنا.", "C": "التعامل مع الغضب أولوية لو ظهر الغضب فعلاً، وغير مذكور بالسؤال.", "D": "الأساس العلمي لل<bdi>treatment</bdi> مهم لاحقًا لكن ليس الأولوية الأولى قبل فهم مخاوفها."},
206: {"A": "الإخبار المباشر بدون تمهيد قاسٍ نفسيًا وقد يصدم الـ<bdi>patient</bdi> دون داعٍ.", "B": "طمأنته بأن لا شيء يستدعي <bdi>anxiety</bdi> كذب واضح يضر بالثقة العلاجية.", "C": "التركيز على نصيحة التدخين فقط يتجاهل الخبر الأساسي المهم الواجب إيصاله."},
207: {"A": "القول إن الإسهال غير خطير قد يكون غير دقيق طبيًا وقد يصل ل<bdi>complication</bdi> خطيرة.", "C": "الموافقة على إيقاف المضادات الضرورية <bdi>risk</bdi> على الـ<bdi>patient</bdi> نفسه المصاب بعدوى فعلية.", "D": "الاعتذار عن استخدام <bdi>treatment</bdi> ضروري طبيًا غير مبرر ولا منطقي."},
191: {"A": "القناع البسيط أقل دقة بالتحكم بتركيز الأكسجين المعطى فعليًا.", "B": "كيس التنفس (rebreathing) يعطي تركيز أكسجين عالٍ غير متحكم به بدقة.", "C": "القنية الأنفية أقل دقة بالتحكم بالتركيز مقارنة بقناع فنتوري."},
192: {"A": "التنفس الصناعي <bdi>step</bdi> تصعيدية تُحجز لو فشل تعديل الأكسجين بتحسين الـ<bdi>case</bdi>.", "C": "أشعة الدماغ غير موجهة هنا لأن الـ<bdi>cause</bdi> الأرجح واضح (تراكم CO2 من الأكسجين الزائد).", "D": "النالوكسون يُستخدم لعكس تأثير المخدرات الأفيونية، لا علاقة له بتخدير ثاني أكسيد الكربون."},
193: {"A": "تغيير الـ<bdi>treatment</bdi> ل<bdi>heparin</bdi> وريدي تصعيد غير مبرر ل<bdi>patient</bdi> مستقرة على <bdi>treatment</bdi> مناسب.", "B": "مذيبات الـ<bdi>thrombus</bdi> تُحجز لحالات عدم الاستقرار الهمودايناميكي، غير موجودة هنا.", "D": "استئصال الـ<bdi>thrombus</bdi> الجراحي <bdi>procedure</bdi> باضع غير مبرر ل<bdi>patient</bdi> مستقرة تستجيب لل<bdi>treatment</bdi> الحالي."},
194: {"A": "فلتر الوريد الأجوف يمنع خثرات جديدة لكنه لا يعالج الـ<bdi>embolism</bdi> الحرج الحالي المهدد للحياة.", "C": "الإينوكسابارين <bdi>treatment</bdi> مناسب لل<bdi>case</bdi> المستقرة، لكن غير كافٍ وحده ب<bdi>case</bdi> صدمة <bdi>severe</bdi>.", "D": "الـ<bdi>warfarin</bdi> يحتاج وقتًا طويلاً ليصل لمستوى علاجي، غير مناسب ب<bdi>case</bdi> إسعافية حرجة."},
195: {"A": "الدبيلة تعطي سائلًا صديديًا مع زرع جرثومي إيجابي، لا ترفع الإنترفيرون غاما بنفس الطريقة.", "B": "الورم المتوسطي يحتاج فحوصات نسيجية وخلوية مختلفة تمامًا لتأكيده.", "C": "الـ<bdi>effusion</bdi> المصاحب ل<bdi>pneumonia</bdi> جرثومي عادي لا يرفع الإنترفيرون غاما بهذا النمط."},
196: {"A": "السبيرومتري تقيّم شدة <bdi>disease</bdi> الرئة الأساسي، لا تقيّم القلب المتأثر ثانويًا.", "C": "دوبلر الأطراف السفلية يفيد لو الشك بتخثر وريدي عميق منفصل، لا <bdi>signs</bdi> القلب الحالية.", "D": "الأشعة المقطعية عالية الدقة تقيّم الرئة نفسها، لا القلب الرئوي المتأثر."},
197: {"A": "مونتيلوكاست دواء <bdi>asthma</bdi>، ليس له دور مثبت بتحسين البقيا بـ COPD.", "B": "الستيرويد الاستنشاقي يقلل النوبات لكن بدون دليل قوي على تحسين البقيا.", "D": "الموسّع طويل المفعول يحسّن الـ<bdi>symptoms</bdi> لكن بدون دليل على تحسين معدل البقيا."},
198: {"A": "مضاد الليكوترايين لوحده أضعف فعالية من الـ<bdi>treatment</bdi> المركب بهالمستوى من الشدة.", "B": "الموسّع طويل المفعول وحده بدون ستيرويد استنشاقي غير آمن ك<bdi>treatment</bdi> مستقل.", "D": "استمرار السالبوتامول وحده غير كافٍ إطلاقًا ل<bdi>symptoms</bdi> ليلية متكررة بهالتكرار."},
199: {"A": "<bdi>asthma</bdi> الحقيقي يعطي <bdi>wheeze</bdi> زفيريًا ويستجيب جيدًا للسالبوتامول، عكس الموصوف هنا.", "B": "الجسم الغريب يسبب انسدادًا ثابتًا مستمرًا، لا نوبات متكررة تتحسن فجأة.", "C": "<bdi>GERD</bdi> لا يفسر ضيق الحلق والـ<bdi>wheeze</bdi> الشهيقي النوبي بهذا النمط المحدد."},
200: {"A": "السبيرومتري تقيّم <bdi>diseases</bdi> الرئة الانسدادية أو التقييدية، لا تشخص اضطراب النوم.", "B": "الأشعة المقطعية تقيّم تركيب الرئة، لا تشخص انقطاع النفس النومي.", "D": "اختبار التحدي بالميثاكولين يشخص فرط الاستجابة القصبية ب<bdi>asthma</bdi>، غير مرتبط بانقطاع النفس النومي."},
181: {"A": "المضادات الحيوية لا تعالج تجمعًا دمويًا ميكانيكيًا بالجنب.", "B": "مضادات التخثر <bdi>risk</bdi> جدًا هنا لأنها تزيد النزف الموجود أصلاً.", "D": "الموسّع القصبي ما له دور ب<bdi>treatment</bdi> تجمع دموي ميكانيكي بالفراغ الجنبي."},
182: {"A": "توسع القصبات لا يرتبط مباشرة بآلية البلهارسيا الكبدية أو ارتفاع الضغط البابي.", "B": "<bdi>pulmonary embolism</bdi> <bdi>case</bdi> <bdi>acute</bdi>، لا تفسر الصورة الـ<bdi>chronic</bdi> التدريجية هنا.", "C": "<bdi>pericarditis</bdi> المضيّق يعطي <bdi>signs</bdi> مختلفة كنبض متناقض وصوت طرقة، غير مذكورة هنا."},
183: {"A": "الأشعة الصدرية العادية قد تكون <bdi>normal</bdi> أو غير نوعية، لا تكفي لتأكيد الـ<bdi>diagnosis</bdi>.", "B": "التنظير القصبي مفيد لأخذ عينات أو إزالة انسداد موضعي، مو الفحص الأول لل<bdi>diagnosis</bdi>.", "D": "وظائف الرئة تقيّم شدة الانسداد الوظيفي، لا تشخص التشريح المرضي نفسه."},
184: {"A": "الـ<bdi>echo</bdi> يعطي <bdi>signs</bdi> غير مباشرة لارتفاع الضغط الرئوي، لا يحدد الـ<bdi>cause</bdi> التخثري الـ<bdi>chronic</bdi>.", "B": "تخطيط القلب يعطي <bdi>signs</bdi> غير نوعية لإجهاد البطين الأيمن، لا يشخص CTEPH.", "C": "التصوير المقطعي بالصبغة أقل حساسية من مسح التهوية والتروية لهالتشخيص بالذات."},
185: {"A": "إنفليكسيماب مضاد ل<bdi>factor</bdi> نخر الورم (TNF)، فئة دوائية مختلفة تمامًا.", "B": "تينوفوفير مضاد فيروسات، غير مرتبط بمستقبلات الليكوترايين.", "D": "فوريكونازول مضاد فطريات، فئة دوائية مختلفة تمامًا."},
186: {"A": "ارتفاع الضغط البابي يصنف ضمن المجموعة 1 من تصنيف منظمة الصحة العالمية.", "B": "قصور البطين الأيسر يصنف ضمن المجموعة 2، لا المجموعة 3.", "C": "الـ<bdi>disease</bdi> التخثري الـ<bdi>chronic</bdi> يصنف ضمن المجموعة 4 المستقلة، لا المجموعة 3."},
187: {"A": "سرطان الغدد يميل للنمو الطرفي أكثر من المركزي، أقل ارتباطًا بمتلازمة الوريد الأجوف.", "B": "السرطانة السرطاوية نادرة وتنمو ببطء، أقل ارتباطًا بهالمتلازمة الـ<bdi>acute</bdi>.", "C": "السرطان الحرشفي مرتبط أكثر بارتفاع الكالسيوم منه بمتلازمة الوريد الأجوف العلوي."},
188: {"A": "الاستئصال الجراحي <bdi>procedure</bdi> متقدم جدًا وغير مبرر قبل أي <bdi>assessment</bdi> أولي بسيط.", "C": "الأشعة المقطعية أكثر تكلفة وتدخلاً من مجرد مراجعة أشعة سابقة متاحة.", "D": "الخزعة بالإبرة <bdi>procedure</bdi> تدخلي غير مبرر قبل التأكد من استقرار العقيدة عبر أشعة سابقة."},
189: {"A": "الشفط بالإبرة يُحجز لاسترواح أكبر حجمًا أو <bdi>patient</bdi> غير مستقر.", "B": "أنبوب الصدر <bdi>procedure</bdi> أكبر من اللازم لاسترواح صغير عند <bdi>patient</bdi> مستقر.", "C": "البلورودزس <bdi>procedure</bdi> وقائي لمنع التكرار، مو لل<bdi>management</bdi> الـ<bdi>acute</bdi> الأولية."},
190: {"A": "زراعة الدم غير موجهة هنا بدون دليل على عدوى دموية نشطة.", "B": "الستيرويد الفموي يُعطى بعد تأكيد الـ<bdi>diagnosis</bdi>، مو ك<bdi>step</bdi> أولى قبل أي <bdi>assessment</bdi>.", "D": "الخزعة الجلدية <bdi>procedure</bdi> تدخلي يُحجز لو احتجنا تأكيدًا نسيجيًا بعد التوجه الأولي بالأشعة."},
171: {"A": "الإبينفرين يُحجز لحساسية مفرطة <bdi>severe</bdi> أو فشل الـ<bdi>treatment</bdi> الأولي، مو كخط أول عادي هنا.", "B": "الستيرويد الاستنشاقي بطيء الأثر ولا يفيد بتخفيف النوبة الـ<bdi>acute</bdi> فورًا.", "D": "المغنيسيوم الوريدي يُضاف للحالات الـ<bdi>severe</bdi> اللي ما استجابت لل<bdi>treatment</bdi> الأولي، مو كخط أول."},
172: {"A": "الـ<bdi>warfarin</bdi> يحتاج وقتًا للوصول لمستوى علاجي فعّال، فما يُستخدم لوحده كبداية.", "B": "الأدوية المذيبة لل<bdi>thrombus</bdi> تُحجز لحالات عدم الاستقرار الـ<bdi>severe</bdi> أو الصدمة.", "D": "فلتر الوريد الأجوف بديل يُستخدم فقط لو منع استخدام مضادات التخثر."},
173: {"A": "مونتيلوكاست دواء <bdi>asthma</bdi> وليس له دور مثبت ب<bdi>treatment</bdi> COPD.", "B": "البريدنيزون يُحجز ل<bdi>treatment</bdi> نوبة التفاقم الـ<bdi>acute</bdi> نفسها مو لل<bdi>treatment</bdi> الـ<bdi>chronic</bdi> اليومي.", "D": "الفورموتيرول نفس فئة السالميتيرول، فإضافته لا تضيف آلية جديدة مختلفة."},
174: {"A": "التيوتروبيوم مضاد كوليني يُستخدم أكثر بـ COPD مو كخط أول ب<bdi>asthma</bdi>.", "C": "البوديسونايد <bdi>treatment</bdi> وقائي يومي يُضاف لاحقًا لو تكررت الـ<bdi>symptoms</bdi> أكثر من مرتين أسبوعيًا.", "D": "مونتيلوكاست أيضًا <bdi>treatment</bdi> وقائي إضافي، مو خط الـ<bdi>treatment</bdi> الأول لل<bdi>symptoms</bdi> المتقطعة."},
175: {"A": "<bdi>asthma</bdi> يعطي انعكاسية أكبر و<bdi>symptoms</bdi> متقطعة، عكس النمط الـ<bdi>chronic</bdi> المستمر هنا.", "C": "<bdi>pulmonary embolism</bdi> <bdi>case</bdi> <bdi>acute</bdi> مفاجئة، لا تفسر كحة منتجة <bdi>chronic</bdi> 3 أشهر.", "D": "<bdi>pulmonary fibrosis</bdi> يعطي نمطًا تقييديًا لا احتباسًا <bdi>chronic</bdi> لثاني أكسيد الكربون بهالشكل."},
176: {"A": "<bdi>tuberculosis</bdi> يحتاج <bdi>symptoms</bdi> <bdi>chronic</bdi> أطول مع تعرّق ليلي وفقدان وزن، ولا يفسر تغير الصوت وألم المعصمين.", "B": "توسع القصبات يعطي بلغمًا غزيرًا <bdi>chronic</bdi>، ولا يفسر بحّة الصوت وألم المعصمين المصاحب.", "C": "<bdi>pulmonary embolism</bdi> <bdi>case</bdi> <bdi>acute</bdi>، لا تفسر تغير الصوت التدريجي ولا اعتلال المعصمين الـ<bdi>chronic</bdi>."},
177: {"A": "الأشعة الصدرية أبطأ وأقل عملية ل<bdi>follow-up</bdi> الاستجابة اللحظية المتكررة أثناء النوبة.", "B": "غازات الدم مفيدة ل<bdi>assessment</bdi> الشدة لكن أبطأ وأقل عملية لل<bdi>follow-up</bdi> المتكررة السريعة.", "C": "النبض المتناقض <bdi>sign</bdi> فحص مساعدة أقل دقة وموضوعية من رقم ذروة الجريان المباشر."},
178: {"A": "<bdi>heart failure</bdi> يعطي <bdi>effusion</bdi> <bdi>bilateral</bdi> غالبًا مع <bdi>signs</bdi> <bdi>congestion</bdi>، ولا يفسر غياب الـ<bdi>shift</bdi> بهالشكل.", "B": "الـ<bdi>effusion</bdi> السلي الـ<bdi>chronic</bdi> عادة يصاحبه <bdi>shift</bdi> متوقع للمنصف بعيدًا عنه بحجمه الكبير.", "C": "<bdi>effusion</bdi> تمزق المريء يصاحب <bdi>symptoms</bdi> هضمية وصدمة إنتانية <bdi>severe</bdi>، غير مذكورة هنا."},
179: {"A": "الإيزونيازيد يسبب اعتلال أعصاب طرفي، مو ارتفاع حمض اليوريك.", "B": "الريفامبيسين يسبب سمية كبدية وتلوين إفرازات، مو ارتفاع حمض اليوريك.", "C": "الإيثامبيوتول يسبب التهاب عصب بصري، مو ارتفاع حمض اليوريك."},
180: {"A": "التليف الكيسي يسبب عقمًا بانسداد القناة الدافقة بدون انعكاس أحشاء.", "C": "<bdi>disease</bdi> ويجنر <bdi>disease</bdi> مناعي ذاتي وعائي، لا يفسر انعكاس الأحشاء ولا العقم بهالآلية.", "D": "متلازمة غودباستشر تصيب الرئة والكلى مناعيًا، ولا علاقة لها بانعكاس الأحشاء أو العقم."},
161: {"A": "فيتامين B6 يُعطى وقائيًا مع الدواء بس ليس فحصًا أساسيًا ضروريًا قبل البدء.", "B": "فحص PPD غير مفيد بعد تأكيد الـ<bdi>diagnosis</bdi> فعليًا بالفحوصات الأخرى.", "C": "سكر الدم غير مرتبط مباشرة بسمية أدوية <bdi>tuberculosis</bdi> الأساسية المحتملة."},
162: {"A": "إيقاف دواء واحد فقط غير كافٍ بهالدرجة الـ<bdi>severe</bdi> من الارتفاع بإنزيمات الكبد.", "B": "نفس الفكرة، إيقاف دواء واحد فقط لا يحمي الكبد بدرجة كافية عند ارتفاع بهالحجم.", "C": "إيقاف دواء واحد فقط لا يكفي، والارتفاع الـ<bdi>severe</bdi> يستدعي إيقاف الجميع لحماية الكبد."},
163: {"A": "نسبة البروتين المعتمدة لتصنيف <bdi>exudative</bdi> هي أكثر من 0.5 وليس أقل منها.", "C": "المعيار الصحيح هو LDH أكثر من ثلثي (2/3) الحد الأعلى الـ<bdi>normal</bdi>، مو ثلثه.", "D": "عدد كريات الدم البيضاء وحده ليس من معايير لايت الرسمية لتصنيف <bdi>exudative</bdi> أو <bdi>transudative</bdi>."},
164: {"B": "pH أعلى من 7.30 يطمئن ل<bdi>effusion</bdi> بسيط غير معقد لا يحتاج تصريفًا عاجلًا.", "C": "سكر أعلى من 80 يدل على <bdi>effusion</bdi> أقل تعقيدًا لا يستدعي تصريفًا فوريًا.", "D": "زرع سلبي يطمئن ولا يدل على وجود عدوى نشطة تستدعي تصريفًا عاجلًا."},
165: {"B": "<bdi>asthma</bdi> يعطي انعكاسية جيدة بعد الموسّعات، عكس ما ذُكر هنا من انسداد ثابت.", "C": "التهاب الشعب الـ<bdi>chronic</bdi> عادة يكون DLCO فيه <bdi>normal</bdi> رغم وجود الانسداد.", "D": "الـ<bdi>disease</bdi> الرئوي الخلالي يعطي نمطًا تقييديًا لا انسداديًا بالسبيرومتري."},
166: {"B": "نسبة FEV1/FVC تنخفض دائمًا بـ COPD، لا ترتفع كما بهذا الخيار.", "C": "السعة الرئوية الكلية ترتفع بـ COPD ب<bdi>cause</bdi> انحباس الهواء، لا تنخفض.", "D": "السعة الحيوية تنخفض بـ COPD ب<bdi>cause</bdi> ضعف الإفراغ، لا تبقى <bdi>normal</bdi>."},
167: {"B": "pH أكثر من 7.20 يطمئن ل<bdi>effusion</bdi> أقل تعقيدًا، عكس المطلوب هنا.", "C": "نسبة PMN وحدها بدون باقي المعايير أقل قوة كمعيار منفرد يستدعي التصريف.", "D": "نسبة البروتين الصحيحة المقلقة تكون أعلى من 0.5 غالبًا، والقيمة هنا أقل من 0.4 تطمئن."},
168: {"A": "بدون بزل تشخيصي، لا نعرف إن كان الـ<bdi>effusion</bdi> معقدًا يحتاج تصريفًا إضافيًا.", "B": "إضافة أوسيلتاميفير غير مبررة بدون دليل على عدوى إنفلونزا موسمية.", "D": "الأشعة المقطعية لا تغني عن أخذ عينة سائل فعلية لتوجيه القرار العلاجي."},
169: {"A": "زرع السائل لل<bdi>tuberculosis</bdi> حساسيته <bdi>low</bdi> جدًا ويحتاج وقتًا طويلاً، أقل حساسية من ADA.", "B": "النمط اللمفاوي الـ<bdi>exudative</bdi> يدعم الـ<bdi>diagnosis</bdi> لكنه أقل نوعية وحساسية من ADA كفحص مفرد.", "C": "السكر الـ<bdi>low</bdi> جدًا يدعم الـ<bdi>diagnosis</bdi> لكنه غير نوعي بما يكفي مقارنة بـ ADA."},
170: {"A": "الثيوفيلين يحسّن الـ<bdi>symptoms</bdi> بس بدون دليل قوي على تحسين معدل البقيا.", "B": "الستيرويدات تقلل النوبات أحيانًا بس ما تثبت تحسين معدل البقيا طويل المدى.", "C": "المقشعات تخفف الـ<bdi>symptoms</bdi> بس ليس لها دليل على تحسين معدل البقيا."},
151: {"B": "خراج الأسنان ليس أثرًا جانبيًا معروفًا مباشرًا للستيرويد الاستنشاقي.", "C": "<bdi>peptic ulcer</bdi> ترتبط أكثر بالستيرويد الفموي الجهازي أو NSAIDs، مو الاستنشاقي الموضعي.", "D": "<bdi>thrombocytopenia</bdi> أثر جانبي غير مرتبط بالستيرويد الاستنشاقي إطلاقًا."},
152: {"A": "الـ COPD شائع بالمدخنين لكن نادرًا ما يسبب تعجّر الأصابع.", "C": "الرشاشيات الرئوية أقل شيوعًا وتحتاج <bdi>factors</bdi> <bdi>risk</bdi> مناعية مختلفة عن مجرد التدخين.", "D": "<bdi>asthma</bdi> <bdi>disease</bdi> انسدادي انتكاسي، ما يرتبط بتعجّر الأصابع ولا بهالتدهور التدريجي الـ<bdi>chronic</bdi>."},
153: {"A": "السالميتيرول موسّع قصبي أصلًا، لا يسبب تشنجًا قصبيًا.", "C": "الرامبريل قد يسبب كحة جافة لكن ليس له آلية مباشرة قوية لتضيق قصبي <bdi>acute</bdi>.", "D": "الـ<bdi>aspirin</bdi> يسبب تشنجًا قصبيًا عند حساسية معروفة له، وهذا غير مذكور بالسؤال."},
154: {"A": "القياس الواحد غير كافٍ، ويحتاج قياسين منفصلين لتأكيد الحاجة للأكسجين الـ<bdi>chronic</bdi>.", "C": "نفس المشكلة، قياس واحد فقط لا يكفي بغض النظر عن القيمة، والعتبة المذكورة أعلى من الصحيحة.", "D": "العتبة المذكورة (أقل من 6.3) أقل من الحد المعتمد فعليًا (أقل من 7.3 kPa)."},
155: {"A": "<bdi>pancreatitis</bdi> الـ<bdi>acute</bdi> يعطي ألمًا <bdi>severe</bdi> مفاجئًا، مو <bdi>symptoms</bdi> <bdi>chronic</bdi> على 4 أشهر.", "B": "ورم البنكرياس أقل شيوعًا بهالعمر وهالسياق المرتبط بالتليف الكيسي.", "C": "الكيس الكاذب يحتاج عادة تاريخ التهاب بنكرياس <bdi>acute</bdi> سابق، غير مذكور هنا."},
156: {"A": "<bdi>asthma</bdi> يتميز بانعكاسية جيدة بعد الستيرويد، عكس ما حصل هنا.", "B": "تليف الرئة يعطي نمطًا تقييديًا بالسبيرومتري مو انسداديًا.", "C": "<bdi>heart failure</bdi> اليساري يعطي <bdi>symptoms</bdi> احتقانية وفحوصات قلبية غير <bdi>normal</bdi>، مذكور أنها <bdi>normal</bdi> هنا."},
157: {"B": "التهاب الفص الأوسط عادة لا يسبب <bdi>shift</bdi> واضحًا بالقصبة بهالدرجة.", "C": "<bdi>pulmonary embolism</bdi> لا يعطي صمم قرع موضعي واضح ولا <bdi>shift</bdi> قصبة بهالشكل.", "D": "الاسترواح الصدري يعطي صوت قرع رنينيًا (طبليًا) مو صمم قرع."},
158: {"B": "الموسّع طويل المفعول يُحجز لل<bdi>asthma</bdi> المستمر الأكثر تكرارًا، مو الـ<bdi>mild</bdi> جدًا هنا.", "C": "مضاد الليكوترايين <bdi>treatment</bdi> وقائي يومي غير مناسب لهالمستوى المتقطع الـ<bdi>mild</bdi>.", "D": "الستيرويد الاستنشاقي اليومي تصعيد غير مبرر ل<bdi>symptoms</bdi> مرة أو مرتين بالأسبوع فقط."},
159: {"A": "البيرازيناميد يسبب سمية كبدية وارتفاع حمض اليوريك، مو اعتلال أعصاب طرفي.", "B": "الإيثامبيوتول يسبب التهاب عصب بصري وتغير رؤية الألوان، مو <bdi>paresthesia</bdi> الأطراف.", "C": "الريفامبيسين يسبب تلوين الإفرازات وسمية كبدية، غير مرتبط ب<bdi>neuropathy</bdi> هذا."},
160: {"B": "زيادة الـ<bdi>furosemide</bdi> غير مبررة لأن الفحص لا يظهر أي <bdi>congestion</bdi> يستدعي ذلك.", "C": "طلب فحص وظائف الرئة غير ضروري لأن الـ<bdi>cause</bdi> الأرجح دوائي واضح مباشرة.", "D": "الموسّع الاستنشاقي لا يعالج <bdi>cause</bdi> الكحة الحقيقي المرتبط بمثبط ACE."},
141: {"A": "توبيخ الـ<bdi>patient</bdi> أسلوب غير فعال ولا يحل مشكلة الالتزام الفعلية.", "B": "إبقاؤه بالمستشفى حل مؤقت فقط وما يحل المشكلة بعد الخروج.", "D": "تهديده بالموت أسلوب تواصل غير أخلاقي وغير فعال لتحسين الالتزام."},
142: {"A": "الأكسجة تتأثر ب<bdi>factors</bdi> كثيرة متغيرة، أقل دقة كمؤشر <bdi>follow-up</bdi> طويل المدى من FEV1.", "B": "عدد النوبات مهم لكن متقلب وما يقيس التدهور الوظيفي المباشر.", "C": "نسبة FEV1/FVC تفيد أكثر بالـ<bdi>diagnosis</bdi> الأولي، مو ب<bdi>follow-up</bdi> شدة التدهور بدقة."},
143: {"A": "الحد المعتمد للنوبة الـ<bdi>severe</bdi> بالأكسجة هو أقل من 92% وليس أقل من 95%.", "C": "الحد المعتمد للنبض بالنوبة الـ<bdi>severe</bdi> هو أكثر من 110 وليس 100.", "D": "الحد المعتمد للـ PEFR بالنوبة الـ<bdi>severe</bdi> هو أقل من 50% من الأفضل الشخصي (حوالي 200 هنا) وليس أقل من 300."},
144: {"A": "إضافة مضاد ليكوترايين تصعيد غير مبرر ل<bdi>patient</bdi> مضبوطة تمامًا منذ سنة.", "B": "<bdi>complication</bdi> جرعة الستيرويد تصعيد خاطئ ل<bdi>patient</bdi> تحتاج تخفيف الـ<bdi>treatment</bdi> لا زيادته.", "C": "إيقاف كل الأدوية دفعة واحدة <bdi>risk</bdi> ويهدد بانتكاسة سريعة لل<bdi>symptoms</bdi>."},
145: {"B": "تجنب الطيران نصيحة مؤقتة محدودة الأثر على تكرار الاسترواح طويل المدى.", "C": "تجنب الرياضة لمدة معينة أقل أهمية من وقف التدخين ك<bdi>factor</bdi> <bdi>risk</bdi> رئيسي.", "D": "الـ<bdi>treatment</bdi> الـ<bdi>normal</bdi> التنفسي ما له دور مباشر بالوقاية من الاسترواح الصدري."},
146: {"B": "قياس IgE النوعي يحدد الحساسية لمادة معينة بس ما يثبت الارتباط الزمني بالعمل نفسه.", "C": "اختبار الوخز الجلدي يقيّم التحسس الجلدي، مو الـ<bdi>symptoms</bdi> التنفسية الفعلية بالعمل.", "D": "اختبار اللصق يستخدم لتحسس الجلد التماسي، غير مرتبط ب<bdi>diagnosis</bdi> <bdi>asthma</bdi> المهني."},
147: {"B": "توسع القصبات <bdi>disease</bdi> انسدادي يعطي نمطًا انسداديًا بالسبيرومتري مو تقييديًا.", "C": "<bdi>heart failure</bdi> ممكن يعطي نمطًا تقييديًا لكن بدون <bdi>signs</bdi> قلبية مذكورة بالسؤال يكون أقل احتمالًا.", "D": "<bdi>asthma</bdi> <bdi>disease</bdi> انسدادي كلاسيكي، يعطي نسبة FEV1/FVC <bdi>low</bdi> مو نمطًا تقييديًا."},
148: {"A": "الـ<bdi>treatment</bdi> التعويضي بالنيكوتين آمن عمومًا عند مرضى <bdi>epilepsy</bdi>.", "B": "السجائر الإلكترونية ليست دواءً موصوفًا ولا تحمل نفس <bdi>risk</bdi> خفض عتبة التشنج.", "C": "الفارينكلين آمن نسبيًا عند مرضى <bdi>epilepsy</bdi> المضبوط مقارنة بالبوبروبيون."},
149: {"A": "معدل نبض 100 أقل من الحد المعتمد لتصنيف النوبة ك<bdi>severe</bdi> (أكثر من 110).", "B": "معدل تنفس أكثر من 20 قيمة حدية وأقل من العتبة الفعلية للنوبة الـ<bdi>severe</bdi>.", "C": "PEFR بقيمة 200 من أصل 300 يعادل تقريبًا 67%، وهذا فوق حد النوبة الـ<bdi>severe</bdi> (33-50%)."},
150: {"B": "معدل تنفس أكثر من 20 قيمة حدية عادية وليست <bdi>sign</bdi> خاصة بالنوبة الـ<bdi>severe</bdi>.", "C": "نبض 100 قيمة <bdi>normal</bdi> نسبيًا وأقل من حد النوبة الـ<bdi>severe</bdi> (أكثر من 110).", "D": "أكسجة 95% <bdi>normal</bdi> نسبيًا ولا تدل على نوبة <bdi>severe</bdi>."},
131: {"A": "خراج الرئة يعطي حمى وبلغم قيح كريه، مو كحة جافة تدريجية بهالصورة.", "B": "توسع القصبات يعطي بلغم غزير <bdi>chronic</bdi>، مو كحة جافة نقية.", "C": "سرطان القصبات يعطي غالبًا <bdi>sign</bdi> موضعية أو نفث دم أكثر من صورة تليف منتشر <bdi>bilateral</bdi>."},
132: {"B": "الصمة الإنتانية من التهاب شغاف القلب تعطي نمطًا مختلفًا وغالبًا نفث دم مع تاريخ قلبي.", "C": "سرطان القصبات المصاحب لعدوى يعطي كتلة موضعية بالأشعة، مو ذكرها هنا.", "D": "الانتشار المباشر من جدار الصدر نادر جدًا ويحتاج عدوى موضعية واضحة بجدار الصدر."},
133: {"A": "المغنيسيوم الوريدي <bdi>treatment</bdi> مساعد بس ما يكفي وحده بفشل تنفسي وشيك.", "B": "الأمينوفيلين <bdi>treatment</bdi> ثانوي أقل فعالية وله <bdi>symptoms</bdi> جانبية، ما يعالج الفشل التنفسي الفوري.", "D": "التنفس الضاغط الأنفي غير مناسب و<bdi>risk</bdi> ب<bdi>case</bdi> ضائقة تنفسية <bdi>severe</bdi> مهددة للحياة."},
134: {"B": "حاصرات الكالسيوم آمنة عمومًا وما تسبب تضيق قصبي.", "C": "حاصرات مستقبلات الأنجيوتنسين لا تؤثر على الشعب الهوائية.", "D": "مثبطات الإنزيم المحول قد تسبب كحة جافة لكن لا تسبب تضيق قصبي أو تفاقم <bdi>asthma</bdi> مباشر."},
135: {"A": "المدرات تفيد باحتباس السوائل الجهازي، مو بتجمع السائل الموضعي بالجنب من ورم.", "B": "غسيل الكلى الترشيحي يستخدم بحالات زيادة الحمل السائلي الكلوي القلبي، غير مرتبط هنا.", "D": "الألبومين الوريدي يرفع الضغط الأسموزي الجهازي، ما يمنع تسرب السائل الموضعي من الورم."},
136: {"A": "مونتيلوكاست دواء <bdi>asthma</bdi>، ما يعالج الـ<bdi>disease</bdi> الحبيبي الالتهابي الأساسي.", "C": "مضاد <bdi>tuberculosis</bdi> غير مناسب لأن الفحوصات تنفي <bdi>tuberculosis</bdi> (PPD سلبي وورم غير متجبن).", "D": "سالميتيرول موسّع قصبي لل<bdi>asthma</bdi>، ما يعالج الساركويدوز."},
137: {"A": "التخدير قد يخفي <bdi>signs</bdi> تدهور الـ<bdi>patient</bdi> وما يعالج مصدر النزف.", "B": "الاستئصال الجراحي <bdi>procedure</bdi> لاحق يُحجز لو استمر النزف رغم الـ<bdi>procedures</bdi> الأولية.", "C": "الـ<bdi>treatment</bdi> الـ<bdi>normal</bdi> الصدري قد يحرّك الإفرازات والدم ويزيد <bdi>risk</bdi> انسداد مجرى الهواء."},
138: {"A": "تجاهل رأي الابن كليًا تصرف غير محترم مهنيًا رغم أن الـ<bdi>treatment</bdi> ضروري.", "C": "قبول رأي الابن مباشرة يعرّض الـ<bdi>patient</bdi> ل<bdi>risk</bdi> حقيقي بحرمانها من <bdi>treatment</bdi> منقذ.", "D": "الـ<bdi>patient</bdi> نفسها غير قادرة على اتخاذ قرار مستقل ب<bdi>cause</bdi> اللخبطة الذهنية الـ<bdi>acute</bdi>."},
139: {"B": "تهديدها بالموت أسلوب ضغط غير أخلاقي وغير مناسب للتواصل الطبي.", "C": "الإيحاء بعدم وجود بديل قد يكون غير دقيق ويضغط على قرارها بدون مبرر.", "D": "التقليل من الـ<bdi>symptoms</bdi> الجانبية يخالف مبدأ الصدق الطبي ويضلل قرارها."},
140: {"A": "القول إن هذا يحصل لأي شخص يبدو كتبرير سريع يتجاهل مخاوف الابن المشروعة.", "B": "الدفاع المسبق بصحة الـ<bdi>treatment</bdi> بدون تحقيق رسمي غير مهني وقد يبدو كتغطية.", "C": "منع الابن من الشكوى ينتهك حقه الأساسي بالمراجعة والمحاسبة."},
121: {"A": "الـ MRI وحده كافٍ بس ما يعالج الوذمة حول الورم اللي تسبب الضغط العصبي.", "B": "الـ<bdi>treatment</bdi> الإشعاعي يحتاج تأكيد <bdi>diagnosis</bdi> أولاً بالـ MRI ومو الـ<bdi>step</bdi> الفورية الأولى.", "C": "عدم اتخاذ أي <bdi>procedure</bdi> <bdi>risk</bdi> جدًا لأن التلف العصبي قد يصير دائم لو تأخرنا."},
122: {"A": "<bdi>renal failure</bdi> يرفع الفوسفات ويعطي صورة مختلفة، وما يفسر انخفاض PTH بهالسياق.", "B": "فرط النشاط الأولي يرفع PTH نفسه، وهنا PTH <bdi>low</bdi>.", "C": "فرط النشاط الثانوي مرتبط بفشل كلوي ويرفع PTH أيضًا، عكس الموجود هنا."},
123: {"A": "الـ COPD ما يفسر فقدان الوزن الكبير والسريع بهالدرجة عادة.", "B": "<bdi>pneumonia</bdi> عادة يعطي حمى و<bdi>symptoms</bdi> <bdi>acute</bdi>، مو تدهور تدريجي 8 أسابيع مع فقدان وزن كبير.", "D": "الـ<bdi>disease</bdi> الرئوي الخلالي أقل ارتباطًا بفقدان الوزن الـ<bdi>severe</bdi> بهالسرعة مقارنة بالورم."},
124: {"A": "الثيامين يعالج نقص فيتامين B1 (يسبب اعتلال أعصاب من <bdi>cause</bdi> مختلف كإدمان الكحول)، مو مرتبط بالإيزونيازيد.", "C": "فيتامين B12 يعالج نقص B12 (مثل <bdi>anemia</bdi> خبيث)، مو آلية الإيزونيازيد هنا.", "D": "الأميتريبتيلين مسكن أعصاب مساعد بس ما يعالج الـ<bdi>cause</bdi> الأساسي (نقص B6)."},
125: {"A": "لقاح BCG يقي جزئيًا الأطفال من الأشكال الـ<bdi>severe</bdi>، مو الـ<bdi>procedure</bdi> الأشمل لمنع الانتشار المجتمعي.", "B": "الـ<bdi>treatment</bdi> الوقائي يستهدف المعرضين للعدوى الكامنة، مو أشمل <bdi>procedure</bdi> وقائي عام.", "C": "التثقيف الصحي مهم بس أقل فعالية مباشرة من <bdi>treatment</bdi> مصدر العدوى نفسه."},
126: {"A": "<bdi>liver cirrhosis</bdi> يعطي <bdi>signs</bdi> كبدية وسوائل بطنية، بدون <bdi>signs</bdi> رئوية وP2 قوي.", "B": "التخثر الوريدي الـ<bdi>bilateral</bdi> نادر جدًا وما يفسر <bdi>signs</bdi> الرئة والقلب الموجودة.", "D": "المتلازمة الكلوية تعطي بروتين بالبول ووذمة شاملة، بدون <bdi>signs</bdi> رئوية مميزة هنا."},
127: {"A": "الأشعة الصدرية قد تلمح لتكبير <bdi>cardiac silhouette</bdi> بس ما تؤكد <bdi>tamponade</bdi> بدقة الـ<bdi>echo</bdi>.", "C": "تخطيط القلب ممكن يبين <bdi>voltage</bdi> <bdi>low</bdi> بس ما يشخص <bdi>tamponade</bdi> بشكل مباشر.", "D": "غازات الدم تقيّم الأكسجين والحموضة، مو تشخص المشكلة الميكانيكية بالقلب."},
128: {"A": "النزف الدموي الواضح بالسائل أشيع بالورم الخبيث أو الرض، مو الـ<bdi>sign</bdi> المميزة للروماتويد.", "B": "<bdi>effusion</bdi> الروماتويد دايمًا <bdi>exudative</bdi> وليس <bdi>transudative</bdi> ب<bdi>cause</bdi> الالتهاب المناعي المباشر.", "C": "الحموضة ب<bdi>effusion</bdi> الروماتويد <bdi>low</bdi> عادة، مو <bdi>elevated</bdi> بهالشكل الـ<bdi>severe</bdi>."},
129: {"B": "الأشعة الصدرية عادة <bdi>normal</bdi> ب<bdi>asthma</bdi> الـ<bdi>mild</bdi> ولا تشخص الـ<bdi>disease</bdi> نفسه.", "C": "غازات الدم الشرياني <bdi>normal</bdi> غالبًا ب<bdi>asthma</bdi> الـ<bdi>mild</bdi> بين النوبات.", "D": "اختبار التحدي بالميثاكولين يُحجز لو السبيرومتري الأساسي <bdi>normal</bdi> رغم الشك السريري."},
130: {"A": "الـ D-dimer يفيد بنفي الـ<bdi>diagnosis</bdi> عند احتمال <bdi>low</bdi>، مو تأكيده عند احتمال عالي.", "B": "السبيرومتري تقيّم وظيفة الرئة الـ<bdi>chronic</bdi>، ما تشخص انسداد وعائي <bdi>acute</bdi>.", "D": "الـ<bdi>echo</bdi> يقيّم الضغط على القلب الأيمن بشكل غير مباشر، مو الفحص الأعلى قيمة لرؤية الـ<bdi>thrombus</bdi> مباشرة."},
111: {"A": "الكليبسيلا <bdi>cause</bdi> أشيع بمرضى الكحول أو الرئة الـ<bdi>chronic</bdi>، مو الأشيع عمومًا بالبالغين.", "B": "الهيموفيلس أشيع بالأطفال أو ضعاف المناعة، مو الـ<bdi>cause</bdi> الأول للالتهاب الفصّي عند البالغين.", "C": "هذي الجرثومة <bdi>cause</bdi> نادر نسبيًا للالتهاب الرئوي الفصّي مقارنة بالمكورات الرئوية."},
112: {"A": "سرطان الرئة يحتاج <bdi>factors</bdi> <bdi>risk</bdi> ومدة أطول وفقدان وزن واضح، غير مذكورين هنا.", "B": "<bdi>tuberculosis</bdi> يحتاج <bdi>symptoms</bdi> أطول من 4 أسابيع مع تعرّق ليلي وفقدان وزن مو مذكورين.", "C": "<bdi>pulmonary embolism</bdi> يبدأ فجأة بدون قصة التهاب صدري سابق يمتد لأسابيع."},
113: {"B": "عدوى الهيموفيلس التهاب <bdi>acute</bdi> يستجيب للمضادات المناسبة، عكس الصورة الـ<bdi>chronic</bdi> هنا.", "C": "عدوى وحيدات النواة تصيب الشباب ب<bdi>symptoms</bdi> <bdi>acute</bdi> وتشفى تلقائيًا، ما تعطي كحة <bdi>chronic</bdi> 3 أشهر.", "D": "المكورات الرئوية تسبب التهاب <bdi>acute</bdi> يستجيب للمضاد المناسب، مو مقاوم بهالشكل."},
114: {"B": "التهاب الشعب الـ<bdi>acute</bdi> ما يعطي ارتشاح فصّي كثيف بالأشعة عادة.", "C": "<bdi>tuberculosis</bdi> يحتاج مدة أطول من يومين ليعطي هالصورة الـ<bdi>acute</bdi>.", "D": "الـ COPD <bdi>disease</bdi> <bdi>chronic</bdi> أساسي، مو <bdi>diagnosis</bdi> الـ<bdi>case</bdi> الـ<bdi>acute</bdi> الحالية بذاتها."},
115: {"A": "الإيبراتروبيوم دواء إنقاذ ثانوي، ما يعالج الالتهاب الـ<bdi>chronic</bdi> المسبب لل<bdi>symptoms</bdi> المتكررة.", "C": "السالبوتامول دواء إنقاذ سريع بس ما يمنع تكرار الـ<bdi>symptoms</bdi> أو يعالج الـ<bdi>cause</bdi>.", "D": "السالميتيرول طويل المفعول لازم يُعطى مع ستيرويد استنشاقي، مو لحاله ك<bdi>treatment</bdi> أول."},
116: {"A": "السالميتيرول طويل المفعول ما يُستخدم بهالطريقة السريعة قبل كل نشاط رياضي.", "C": "البوديسونايد <bdi>treatment</bdi> وقائي يومي <bdi>chronic</bdi>، مو دواء يُعطى قبل المجهود مباشرة.", "D": "الإيبراتروبيوم أبطأ بداية مفعول وأقل فعالية من السالبوتامول بهالسياق."},
117: {"A": "الثيوفيلين إضافة غير مناسبة قبل التأكد من تقنية الاستخدام الصحيحة.", "B": "مضاد الليكوترايين <bdi>step</bdi> تصعيد سابقة لأوانها قبل تصحيح المشكلة الأساسية.", "D": "ما فيه دليل بالسؤال على ارتجاع مريئي يبرر علاجه ك<bdi>step</bdi> أولى."},
118: {"A": "احتشاء القلب يعطي تغيرات تخطيط شريانية موضعية، مو نمط S1Q3T3.", "B": "سرطان الرئة القصبي <bdi>disease</bdi> تدريجي <bdi>chronic</bdi>، ما يعطي بداية <bdi>acute</bdi> بهالشكل.", "D": "<bdi>pericarditis</bdi> يعطي ارتفاع منتشر بالـ ST مو نمط إجهاد البطين الأيمن."},
119: {"B": "الأشعة المقطعية عالية الدقة ما تخفف ضيق النفس الـ<bdi>acute</bdi> ولا تعطي عينة سائل.", "C": "أنبوب الصدر تحت الماء <bdi>procedure</bdi> أكبر من اللازم ك<bdi>step</bdi> أولى ل<bdi>effusion</bdi> يحتاج <bdi>assessment</bdi> بس.", "D": "موسّعات الشعب ما تفيد ب<bdi>case</bdi> ضغط ميكانيكي من سائل متجمع بالجنب."},
120: {"B": "احتشاء القلب يعطي عادة ألم صدر ضاغط وتغيرات تخطيط مميزة، مو ذكرها بالسؤال.", "C": "تسرع البطين يعطي <bdi>palpitations</bdi> منتظم سريع بدون ارتباط واضح بجراحة حديثة.", "D": "انتفاخ الرئة <bdi>disease</bdi> <bdi>chronic</bdi> تدريجي، ما يظهر فجأة بهالتوقيت بعد الجراحة."},
})

